from storage_client import get_container_client
from storage_models import ListPrefixRequest, ListPrefixResponse

def list_prefix(request: ListPrefixRequest) -> ListPrefixResponse:
    container_client = get_container_client(request.container_name)
    blob_names = []
    for blob in container_client.list_blobs(name_starts_with=request.prefix):
        blob_names.append(blob.name)
    return ListPrefixResponse(blobs=blob_names)

import os
from openai import OpenAI

from storage_models import StoredAssetSummaryRequest, StoredAssetSummaryResponse

def stored_asset_summary(request: StoredAssetSummaryRequest) -> StoredAssetSummaryResponse:
    api_key = os.getenv("OPENAI_API_KEY")
    if not api_key:
        raise ValueError("OPENAI_API_KEY environment variable not set.")

    client = OpenAI(api_key=api_key)

    prompt = f"Summarize the following text in about {request.summary_length} words: {request.text}"

    response = client.chat.completions.create(
        model="gpt-3.5-turbo",  # Concrete model identifier
        messages=[
            {"role": "system", "content": "You are a helpful assistant that summarizes text."},
            {"role": "user", "content": prompt}
        ],
        max_tokens=request.summary_length * 2, # Allow more tokens for output safety
        temperature=0.7,
    )

    summary = response.choices[0].message.content.strip()
    return StoredAssetSummaryResponse(summary=summary)

import os
from openai import OpenAI

from storage_models import AssetMetadataEmbeddingRequest, AssetMetadataEmbeddingResponse

def asset_metadata_embedding(request: AssetMetadataEmbeddingRequest) -> AssetMetadataEmbeddingResponse:
    api_key = os.getenv("OPENAI_API_KEY")
    if not api_key:
        raise ValueError("OPENAI_API_KEY environment variable not set.")

    client = OpenAI(api_key=api_key)

    # Combine text content and metadata into a single string for embedding
    metadata_str = " ".join([f"{k}: {v}" for k, v in request.metadata.items()])
    text_to_embed = f"{request.text_content} {metadata_str}".strip()

    if not text_to_embed:
        return AssetMetadataEmbeddingResponse(embedding=[])

    response = client.embeddings.create(
        input=[text_to_embed],
        model="text-embedding-ada-002"  # Concrete model identifier
    )

    embedding = response.data[0].embedding
    return AssetMetadataEmbeddingResponse(embedding=embedding)
